def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Considers parentheses (), square brackets [], and curly braces {}.
    Ignores all other characters.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    open_set = set(pairs.values())
    stack = []
    for ch in s:
        if ch in open_set:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

