    """Count the number of islands (connected groups of 1s) in a possibly jagged grid.
    Cells are connected orthogonally (up, down, left, right). Handles empty grid and empty rows.
    """
    if not grid:
        return 0
    visited = set()
    def get_neighbors(i, j):
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if ni < 0 or nj < 0:
                continue
            if ni >= len(grid):
                continue
            if nj >= len(grid[ni]):
                continue
            yield ni, nj
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            if y >= len(grid[x]):
                continue
            if grid[x][y] != 1:
                continue
            visited.add((x, y))
            for nx, ny in get_neighbors(x, y):
                if (nx, ny) not in visited:
                    stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count
"}

