{"task_id": "T35", "code": "def solve(grid):
    """Count islands in a grid where any non-zero value is land.
    Handles rectangular and jagged grids, empty grid, and empty rows.
    """
    if not grid:
        return 0
    visited = set()
    n = len(grid)
    def get_neighbors(i, j):
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if ni < 0 or nj < 0:
                continue
            if ni >= n:
                continue
            if nj >= len(grid[ni]):
                continue
            yield ni, nj
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            if y >= len(grid[x]):
                continue
            if not grid[x][y]:  # zero or falsy is water
                continue
            visited.add((x, y))
            for nx, ny in get_neighbors(x, y):
                if (nx, ny) not in visited:
                    stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count
