def solve(intervals):
    # Robust merge intervals handling possible malformed inner entries.
    # Filter out entries that are not two-element sequences.
    clean = []
    for iv in intervals:
        if not hasattr(iv, '__len__') or len(iv) != 2:
            continue
        start, end = iv[0], iv[1]
        # Ensure numeric types (int/float) and order start <= end
        try:
            start = int(start)
            end = int(end)
        except Exception:
            continue
        if start > end:
            start, end = end, start
        clean.append([start, end])
    if not clean:
        return []
    clean.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = clean[0]
    for start, end in clean[1:]:
        if start <= cur_end:  # overlap or touch
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

