def solve(nums):
    # Patience sorting method, O(n log n)
    import bisect
    tails = []
    for x in nums:
        # find insertion point in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

