def solve(tokens):
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero as per problem statement
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                stack.append(int(a / b))
        else:
            stack.append(int(tok))
    return stack[-1] if stack else 0

